//! The false-positive canary.
//!
//! This is what an ordinary, honest build script does: read files under the
//! manifest directory, generate Rust into `OUT_DIR`, ask a compiler for its
//! version, emit `cargo:` directives. It is modelled on the shape shared by `cc`,
//! `bindgen`, `pkg-config`, `prost-build` and `vergen` — spawn a tool, read
//! inputs, write generated output under `OUT_DIR`, tell cargo what changed.
//!
//! **The suite asserts this produces ZERO violations under the default policy.**
//! That assertion is the whole reason the fixture exists. A default-deny policy
//! that breaks common crates on day one is dead on arrival, so "we did not catch
//! the malicious one" and "we broke the honest one" are equally failing tests, and
//! only this fixture can fail the second way.

use std::io::Write;
use std::path::Path;

fn main() {
    println!("cargo:rerun-if-changed=build.rs");
    println!("cargo:rerun-if-changed=inputs/table.txt");
    println!("cargo:rerun-if-env-changed=BENIGN_FLAVOUR");

    let manifest = std::env::var("CARGO_MANIFEST_DIR").expect("cargo sets this");
    let out = std::env::var("OUT_DIR").expect("cargo sets this");

    // Reading under the manifest dir: every code generator does this, and the
    // default policy allows reads everywhere.
    let table = std::fs::read_to_string(Path::new(&manifest).join("inputs/table.txt"))
        .unwrap_or_else(|_| "alpha\nbeta\ngamma\n".to_string());

    // Generating into OUT_DIR: the one write every build script must be allowed.
    let mut f = std::fs::File::create(Path::new(&out).join("table.rs")).expect("OUT_DIR is writable");
    writeln!(f, "/// Generated by benign/build.rs. Do not edit.").unwrap();
    writeln!(f, "pub const ENTRIES: &[&str] = &[").unwrap();
    for line in table.lines().filter(|l| !l.trim().is_empty()) {
        writeln!(f, "    {:?},", line.trim()).unwrap();
    }
    writeln!(f, "];").unwrap();

    // A nested directory under OUT_DIR, the way cc's object directory works.
    let objs = Path::new(&out).join("objs");
    std::fs::create_dir_all(&objs).expect("OUT_DIR subdirectories are writable");
    std::fs::write(objs.join("stub.o"), b"\x7fELF-not-really").expect("write into OUT_DIR/objs");

    // Atomic-rename-into-OUT_DIR: what a careful generator does, and the case that
    // needs Landlock ABI v2's REFER right. Under ABI v1 a cross-directory rename is
    // refused, so this line is also the regression test for the tool granting the
    // whole of OUT_DIR as one hierarchy rather than per-file.
    let staged = Path::new(&out).join("table.rs.tmp");
    std::fs::write(&staged, b"// staged\n").expect("staging write");
    std::fs::rename(&staged, Path::new(&out).join("table.staged.rs")).expect("rename within OUT_DIR");

    // Create a subdirectory, put something in it, and remove the lot. Every generator
    // that probes something cleans up after itself, and this is the shape `proc-macro2`'s
    // compiler probe uses.
    //
    // **It is here because of a measured false positive, and it is the regression test for
    // it.** `std::fs::remove_dir_all` does not delete by absolute path: since it was
    // hardened against symlink races it opens the directory and issues
    // `unlinkat(dirfd, "name", …)` with a bare filename. A supervisor that read that path
    // verbatim compared `stub.o` against a list of absolute writable roots, matched
    // nothing, and recorded an ungranted write for a build script that never left OUT_DIR.
    // Measured on 2026-09-15 against a graph of libc, libz-sys, openssl-sys, bindgen and
    // ring: five false findings, every one of them this, and no true ones.
    let probe = Path::new(&out).join("probe");
    std::fs::create_dir_all(probe.join("nested")).expect("OUT_DIR subdirectories are writable");
    std::fs::write(probe.join("nested/stub.o"), b"probe").expect("write into OUT_DIR/probe");
    std::fs::remove_dir_all(&probe).expect("removing what we just made in OUT_DIR");

    // Spawning a compiler to ask its version: `cc`, `pkg-config` and `protoc`
    // wrappers all start this way. Recorded as an exec event, never a violation
    // under the default policy.
    match std::process::Command::new("cc").arg("--version").output() {
        Ok(_) => println!("cargo:rustc-cfg=have_cc"),
        Err(_) => println!("cargo:warning=no cc on PATH; continuing"),
    }

    // Temporary files. Many generators use TMPDIR rather than OUT_DIR, which is
    // why `tmp` is in the default write zone set.
    let tmp = std::env::temp_dir().join(format!("benign-probe-{}", std::process::id()));
    let _ = std::fs::write(&tmp, b"probe");
    let _ = std::fs::remove_file(&tmp);

    println!("cargo:rustc-env=BENIGN_TABLE_LEN={}", table.lines().count());
}
